from pathlib import Path

PATH = Path('index.html')
html = PATH.read_text(encoding='utf-8')


def once(old: str, new: str, label: str):
    global html
    n = html.count(old)
    if n != 1:
        raise SystemExit(f'{label}: expected 1 match, got {n}')
    html = html.replace(old, new, 1)


once('<div class="label">Чистая прибыль</div><div class="num" id="mProfit">0 ₸</div>',
     '<div class="label">Прибыль</div><div class="num" id="mProfit">0 ₸</div>',
     'dashboard profit label')
once('<div class="label">Чистая прибыль</div><div class="num" id="rProfit">0 ₸</div>',
     '<div class="label">Прибыль</div><div class="num" id="rProfit">0 ₸</div>',
     'report profit label')

old_helpers = "function stockTotal(){return state.products.reduce((a,p)=>a+p.stock,0)}function reserved(p){return state.reservations.filter(r=>r.productId===p.id&&r.active).reduce((a,r)=>a+r.qty,0)}function salesDays(p,days=30){let since=Date.now()-days*86400000;return state.sales.filter(s=>s.productId===p.id&&s.date>=since).reduce((a,s)=>a+s.qty,0)/days}function costOf(p){return p.cost||0}function log(type,pid,qty,extra=''){state.movements.unshift({id:id(),date:Date.now(),type,productId:pid,qty,extra});state.movements=state.movements.slice(0,1000)}"
new_helpers = """function stockTotal(){return state.products.reduce((a,p)=>a+(Number(p.stock)||0),0)}
function reserved(p){return state.reservations.filter(r=>r.productId===p.id&&r.active).reduce((a,r)=>a+(Number(r.qty)||0),0)}
function isCompletedOrder(market,status){const s=String(status||'').toUpperCase();return market==='WB'?['COMPLETE','COMPLETED'].includes(s):s==='COMPLETED'}
function financialSales(){const result=[...(state.sales||[])],seen=new Set(result.map(s=>s.externalKey).filter(Boolean));for(const [market,feed] of [['Kaspi',state.kaspiOrderFeed],['WB',state.wbOrderFeed],['Ozon',state.ozonOrderFeed]]){for(const o of(feed||[])){if(!isCompletedOrder(market,o.status)||!o.productId)continue;const key=String(o.orderId)+':'+String(o.entryId);if(seen.has(key))continue;const p=prod(o.productId);if(!p)continue;const qty=Math.max(0,Number(o.qty)||0);if(!qty)continue;const total=Number(o.totalPrice)||0;const price=Number(o.unitPrice)||(total/qty)||0;result.push({id:'virtual-'+market+'-'+key,productId:p.id,qty,price,cost:Number(p.cost)||0,fee:0,channel:market,date:toTimestamp(o.creationDate),externalKey:key,virtual:true});seen.add(key)}}return result}
function salesDays(p,days=30){let since=Date.now()-days*86400000;return financialSales().filter(s=>s.productId===p.id&&s.date>=since).reduce((a,s)=>a+(Number(s.qty)||0),0)/days}
function profitForProduct(p,days=30){let since=Date.now()-days*86400000;return financialSales().filter(s=>s.productId===p.id&&s.date>=since).reduce((a,s)=>a+(Number(s.qty)||0)*((Number(s.price)||0)-(Number(s.cost)||0)-(Number(s.fee)||0)),0)}
function costOf(p){return Number(p.cost)||0}
function log(type,pid,qty,extra=''){state.movements.unshift({id:id(),date:Date.now(),type,productId:pid,qty,extra});state.movements=state.movements.slice(0,1000)}"""
once(old_helpers, new_helpers, 'financial helpers')

once("  let ss=state.sales.filter(s=>s.date>=since);", "  let ss=financialSales().filter(s=>s.date>=since);", 'dashboard financial sales')

old_products = "a.sort((x,y)=>s==='name'?x.name.localeCompare(y.name):s==='stock'?y.stock-x.stock:s==='sales'?salesDays(y)-salesDays(x):s==='profit'?(y.totalProfit||0)-(x.totalProfit||0):salesDays(x)?x.stock/salesDays(x)-y.stock/salesDays(y):0);"
new_products = "a.sort((x,y)=>s==='name'?x.name.localeCompare(y.name):s==='stock'?y.stock-x.stock:s==='sales'?salesDays(y)-salesDays(x):s==='profit'?profitForProduct(y)-profitForProduct(x):salesDays(x)?x.stock/salesDays(x)-y.stock/salesDays(y):0);"
once(old_products, new_products, 'product profit sorting')

