new_card = "function productCard(p){let r=reserved(p),d=salesDays(p),profit=profitForProduct(p);return `<div class=\"item row\" onclick=\"openProduct('${p.id}')\">${p.photo?`<img class=\"thumb\" src=\"${p.photo}\">`:'<div class=\"thumb\">Фото</div>'}<div class=\"grow\"><div class=\"name\">${esc(p.name)}</div><div class=\"muted\">${esc(p.category||'Без категории')}</div><div class=\"muted\">Продажи/день: ${d.toFixed(1)} · Запас: ${d?(p.stock/d).toFixed(1):'∞'} дн.</div><div class=\"muted\">Себестоимость: ${fmt(p.cost)} · Прибыль 30д: ${fmt(profit)}</div></div><div class=\"right\"><b>${p.stock}</b><div class=\"muted\">шт.</div>${r?`<div class=\"badge\">резерв ${r}</div>`:''}</div></div>`}"
