old_reports = "function renderReports(){let since=Date.now()-30*86400000,ss=state.sales.filter(s=>s.date>=since),rev=ss.reduce((a,s)=>a+s.qty*s.price,0),cost=ss.reduce((a,s)=>a+s.qty*s.cost,0),fees=ss.reduce((a,s)=>a+s.qty*s.fee,0);document.getElementById('rRevenue').textContent=fmt(rev);document.getElementById('rCost').textContent=fmt(cost);document.getElementById('rFees').textContent=fmt(fees);document.getElementById('rProfit').textContent=fmt(rev-cost-fees);let names=['Kaspi','WB','Ozon','Ручная'];document.getElementById('mpReport').innerHTML=names.map(n=>{let a=ss.filter(s=>s.channel===n);return `<div class=\"item row\"><div class=\"grow\"><b>${n}</b><div class=\"muted\">${a.reduce((x,s)=>x+s.qty,0)} шт.</div></div><b>${fmt(a.reduce((x,s)=>x+s.qty*s.price,0))}</b></div>`}).join('')}"
new_reports = "function renderReports(){let since=Date.now()-selectedPeriod*86400000,ss=financialSales().filter(s=>s.date>=since),rev=ss.reduce((a,s)=>a+(Number(s.qty)||0)*(Number(s.price)||0),0),cost=ss.reduce((a,s)=>a+(Number(s.qty)||0)*(Number(s.cost)||0),0),fees=ss.reduce((a,s)=>a+(Number(s.qty)||0)*(Number(s.fee)||0),0);document.getElementById('rRevenue').textContent=fmt(rev);document.getElementById('rCost').textContent=fmt(cost);document.getElementById('rFees').textContent=fmt(fees);document.getElementById('rProfit').textContent=fmt(rev-cost-fees);let names=['Kaspi','WB','Ozon','Ручная'];document.getElementById('mpReport').innerHTML=names.map(n=>{let a=ss.filter(s=>s.channel===n),channelRev=a.reduce((x,s)=>x+(Number(s.qty)||0)*(Number(s.price)||0),0),channelProfit=a.reduce((x,s)=>x+(Number(s.qty)||0)*((Number(s.price)||0)-(Number(s.cost)||0)-(Number(s.fee)||0)),0);return `<div class=\"item row\"><div class=\"grow\"><b>${n}</b><div class=\"muted\">${a.reduce((x,s)=>x+(Number(s.qty)||0),0)} шт. · прибыль ${fmt(channelProfit)}</div></div><b>${fmt(channelRev)}</b></div>`}).join('')}"
once(old_reports, new_reports, 'reports')

