new_open = "function openProduct(pid){let p=prod(pid),r=reserved(p),profit=profitForProduct(p),value=(Number(p.stock)||0)*(Number(p.cost)||0);let s=`<h3>${esc(p.name)}</h3><div class=\"item\"><div class=\"row\"><div class=\"grow\"><b>Остаток</b><div class=\"muted\">Резерв: ${r} · Свободно: ${p.stock-r}</div></div><b>${p.stock} шт.</b></div><div class=\"muted\" style=\"margin-top:7px\">Себестоимость: ${fmt(p.cost)} / шт. · Стоимость остатка: ${fmt(value)} · Прибыль 30д: ${fmt(profit)}</div></div><div class=\"item\" style=\"margin-top:8px\"><b>Артикулы</b><div class=\"muted\">Kaspi: ${esc(p.kaspi||'—')} · WB: ${esc(p.wb||'—')} · Ozon: ${esc(p.ozon||'—')}</div></div><button class=\"btn dark full\" onclick=\"closeModal();openModal('edit','${pid}')\">Редактировать товар</button><button class=\"btn full\" onclick=\"closeModal();openModal('writeoff','${pid}')\">Списать</button><button class=\"btn full\" onclick=\"closeModal();openModal('inventory','${pid}')\">Инвентаризация</button>`;showSheet(s)}"
