old_arrival = "function createArrival(){let p=prod(document.getElementById('ap').value),q=+document.getElementById('aq').value||0,c=+document.getElementById('ac').value||0,d=+document.getElementById('ad').value||0,b=document.getElementById('ab').value||'';if(!p||q<=0)return alert('Проверьте данные');let old=p.stock,total=p.cost*old+c*q+d;p.stock+=q;p.cost=p.stock?total/p.stock:0;state.purchases.unshift({id:id(),productId:p.id,qty:q,unitCost:c,delivery:d,batch:b,date:Date.now()});log('приход',p.id,q,`партия ${b}`);save();closeModal();render()}"
new_arrival = "function createArrival(){let p=prod(document.getElementById('ap').value),q=+document.getElementById('aq').value||0,c=Math.max(0,+document.getElementById('ac').value||0),d=Math.max(0,+document.getElementById('ad').value||0),b=document.getElementById('ab').value||'';if(!p||q<=0)return alert('Проверьте данные');const oldQty=Math.max(0,Number(p.stock)||0),newPositiveQty=oldQty+q,total=(Number(p.cost)||0)*oldQty+c*q+d;p.stock=(Number(p.stock)||0)+q;if(newPositiveQty>0)p.cost=total/newPositiveQty;state.purchases.unshift({id:id(),productId:p.id,qty:q,unitCost:c,delivery:d,batch:b,date:Date.now()});log('приход',p.id,q,`партия ${b}`);save();closeModal();render()}"
once(old_arrival, new_arrival, 'arrival costing')

