if 'recalcCostAfterLoss(' in html:
    raise SystemExit('legacy recalcCostAfterLoss call/function remains')
for marker in ['id="pcost"', 'id="ecost"', 'function financialSales()', 'id="sfee"', 'Прибыль 30д']:
    if marker not in html:
        raise SystemExit(f'missing marker: {marker}')

